{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C196", "C202"],
  "contradictory_card_ids": ["C01", "C17", "C05", "C03", "C08", "C18", "C14"],
  "prediction_basis_card_ids": ["C196", "C202"],
  "claims": [
    {
      "claim": "CP-409,092, the closest analog sharing the query's methylaminomethyl phenyl group, has approximately 4-fold higher MAO-A-mediated mitochondrial intrinsic clearance than sumatriptan, matching a 4-fold higher in vivo unbound oral clearance in humans.",
      "card_ids": ["C196", "C202"]
    },
    {
      "claim": "Sumatriptan, the comparator, has low absolute oral bioavailability around 15%, below the 20% threshold; the 4-fold higher MAO-A clearance of the close analog indicates substantial presystemic loss for this methylaminomethyl phenyl indole class.",
      "card_ids": ["C196", "C202"]
    },
    {
      "claim": "Human liver microsome data for CP-409,092 show low CYP-mediated intrinsic clearance of 4 to 9 ml/min/kg, so the dominant first-pass liability is MAO-A, which standard microsomal stability assays do not capture.",
      "card_ids": ["C194", "C203", "C207", "C223"]
    },
    {
      "claim": "Direct L1 human F values for structurally distinct molecules such as safinamide 95%, aprepitant 59-67%, and tegoprazan 86-100% do not address the query's MAO-A substrate pharmacophore and are outweighed by the close-analog clearance evidence.",
      "card_ids": ["C01", "C03", "C14"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C196", "C202", "C194", "C203"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query or for CP-409,092.",
    "The query's own MAO-A substrate status is not directly measured; the inference relies on the shared methylaminomethyl phenyl pharmacophore with CP-409,092.",
    "The effect of lactam rigidification and the indole fluorine on the MAO-A oxidation rate is unknown.",
    "Dose, formulation, and prandial state effects on the query are unknown."
  ],
  "decision_summary": "L6 adds human mitochondrial and microsomal clearance data for CP-409,092, the closest structural analog sharing the query's methylaminomethyl phenyl group. CP-409,092 has about 4-fold higher MAO-A-mediated intrinsic clearance than sumatriptan and a 4-fold higher in vivo unbound oral clearance in humans; sumatriptan's oral bioavailability is about 15%, below the 20% threshold. This is coherent measured first-pass clearance evidence for the query's structural class, supporting F below 20%. Low CYP clearance in liver microsomes does not remove the MAO-A liability. The prediction is flipped to low with moderate confidence."
}

